        private static object? JsonElementToObject(JsonElement element)
        {
            switch (element.ValueKind)
            {
                case JsonValueKind.Object:
                    {
                        var dict = new Dictionary<string, object?>();
                        foreach (var prop in element.EnumerateObject())
